class_name StoryInterpreter
extends Node

# Mappa che associa il nome dell'etichetta alla sua posizione nell'array dei comandi
var _labels: Dictionary = {}
var _commands: Array = []
var _current_index: int = 0

@export var choice_menu: ChoiceMenu


func load_story(commands: Array) -> void:
	_commands = commands
	_current_index = 0
	_labels.clear()

	# Pre-indicizzazione di tutte le etichette per salti veloci
	for i in range(_commands.size()):
		var cmd: Dictionary = _commands[i]
		if cmd.get("type", "") == "label":
			var label_id := String(cmd.get("id", ""))
			_labels[label_id] = i


func execute_next_command() -> void:
	if _current_index >= _commands.size():
		return

	var cmd: Dictionary = _commands[_current_index]
	var cmd_type := String(cmd.get("type", ""))

	match cmd_type:
		"label":
			# Le etichette sono solo segnaposto: passa subito al comando successivo
			_current_index += 1
			execute_next_command()
		"jump":
			var target := String(cmd.get("target", ""))
			jump_to_label(target)
			execute_next_command()
		"choice":
			var options: Array = cmd.get("options", [])
			choice_menu.show_choices(options)
			# Sospende l'esecuzione finche il giocatore non seleziona un'opzione
			var selected_target: String = await choice_menu.choice_selected
			jump_to_label(selected_target)
			execute_next_command()


func jump_to_label(label_id: String) -> void:
	if _labels.has(label_id):
		_current_index = _labels[label_id]
	else:
		push_error("Etichetta non trovata: " + label_id)
